// 클라우드 저장: Firebase 익명 로그인 + Firestore에 진행 상황 백업
// - 게임은 폰 저장(localStorage)만으로 동작하고, 이 모듈은 그걸 클라우드와 맞춰주기만 함
// - 인터넷이 없거나 설정이 비어 있으면 조용히 아무것도 안 함
// - 빌드: npm run build → www/cloud.js (Firebase SDK를 한 파일로 묶어서 오프라인에서도 로드됨)
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, onAuthStateChanged } from 'firebase/auth';
// Lite 버전: 실시간 동기화·오프라인 캐시가 없는 대신 훨씬 가벼움 (폰 저장은 게임이 직접 하므로 충분)
import { getFirestore, doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore/lite';

const SAVE_DELAY_MS = 1500; // 연속 저장을 모아서 한 번에 보냄

let playerRef = null; // Firestore 문서: players/{익명 사용자 uid}
let pending = null;   // 아직 못 보낸 진행 상황
let timer = null;

// 두 진행 상황 합치기: 별과 최고 점수는 큰 값, 마지막 스테이지는 더 최근에 저장된 쪽
function merge(a, b) {
  const maxEach = (x = {}, y = {}) => {
    const out = { ...x };
    for (const [k, v] of Object.entries(y)) out[k] = Math.max(out[k] || 0, v);
    return out;
  };
  const newer = (a.updated || 0) >= (b.updated || 0) ? a : b;
  return {
    stars: maxEach(a.stars, b.stars),
    best: maxEach(a.best, b.best),
    last: newer.last || 0,
    updated: Math.max(a.updated || 0, b.updated || 0),
  };
}

async function flush() {
  if (!playerRef || !pending) return;
  const data = pending;
  pending = null;
  try {
    await setDoc(playerRef, { progress: data, updatedAt: serverTimestamp() });
  } catch (e) {
    pending = pending || data; // 실패하면 다음 저장 때 다시 시도
  }
}

async function currentUser(auth) {
  const user = await new Promise((resolve) => {
    const off = onAuthStateChanged(auth, (u) => { off(); resolve(u); });
  });
  return user || (await signInAnonymously(auth)).user;
}

window.cloud = {
  // 시작할 때 한 번: 로그인 → 클라우드 기록과 합치기 → onMerged(합친 결과)
  async start(local, onMerged) {
    const config = window.FIREBASE_CONFIG;
    if (!config || !config.apiKey) return;
    try {
      const app = initializeApp(config);
      const user = await currentUser(getAuth(app));
      playerRef = doc(getFirestore(app), 'players', user.uid);
      const snap = await getDoc(playerRef);
      const merged = snap.exists() ? merge(local, snap.data().progress || {}) : local;
      onMerged(merged);
      pending = merged;
      await flush();
    } catch (e) {
      console.warn('[cloud] 동기화 안 됨:', e.message);
    }
  },

  // 진행 상황이 바뀔 때마다 호출 (잠깐 모았다가 저장)
  save(progress) {
    pending = JSON.parse(JSON.stringify(progress));
    clearTimeout(timer);
    timer = setTimeout(flush, SAVE_DELAY_MS);
  },
};

function loadProgress() {
  const empty = { stars: {}, best: {}, last: 0 };
  try {
    const saved = JSON.parse(localStorage.getItem(SAVE_KEY));
    if (saved) return { ...empty, ...saved };
    // 예전 버전(별만 저장)에서 옮겨오기
    const oldStars = JSON.parse(localStorage.getItem('run2048-stars'));
    if (oldStars) return { ...empty, stars: oldStars };
  } catch {}
  return empty;
}
function saveProgress() {
  progress.updated = Date.now();
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(progress)); } catch {}
  window.cloud?.save(progress); // 클라우드 백업 (cloud.js, 없으면 무시)
}

// 클라우드 기록과 합친 결과를 반영 (다른 기기·재접속에서 더 좋은 기록이 있으면 가져옴)
function applyCloudProgress(merged) {
  Object.assign(progress.stars, merged.stars);
  Object.assign(progress.best, merged.best);
  progress.last = merged.last;
  progress.updated = merged.updated;
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(progress)); } catch {}
  if (state === 'menu') showStageSelect();
}

const totalBest = () => Object.values(progress.best).reduce((a, b) => a + b, 0);

const sleep = (ms) => new Promise((res) => setTimeout(res, ms));

// ---------- 렌더링 ----------

function place(el, r, c) {
  // 화면상 행 = r + 1 (맨 윗줄은 생성 대기 줄)
  el.style.transform = `translate(${c * 100}%, ${(r + 1) * 100}%)`;
}

function formatValue(v) {
  return v < 100000 ? String(v) : Math.round(v / 1000) + 'K';
$('backBtn').addEventListener('click', showStageSelect);
window.addEventListener('resize', resize);
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state === 'playing') togglePause();
});

// ---------- 시작 ----------

setupBoard();
showStageSelect();
window.cloud?.start(JSON.parse(JSON.stringify(progress)), applyCloudProgress);
requestAnimationFrame((ts) => { lastTs = ts; requestAnimationFrame(loop); });

