import { getAuth, signInAnonymously } from 'firebase/auth';
import { getFirestore, doc, setDoc, updateDoc, getDoc, getDocs, collection, query, orderBy, limit, where, getCount, serverTimestamp } from 'firebase/firestore/lite';
const app = initializeApp({ apiKey: 'AIzaSyB2YASbYqZRZ36X5oiaoUfZQ9R1qf7odIw', authDomain: 'stages-861a3.firebaseapp.com', projectId: 'stages-861a3', appId: '1:374690130385:web:c6528383ed83decbdf98f0' });
const { user } = await signInAnonymously(getAuth(app));
const db = getFirestore(app);
const ref = (uid = user.uid, s = '0') => doc(db, 'stages', s, 'scores', uid);
const t = async (label, expectOk, fn) => { try { await fn(); console.log(expectOk ? 'PASS' : 'FAIL', label, '(allowed)'); } catch (e) { console.log(expectOk ? 'FAIL' : 'PASS', label, '(' + e.code + ')'); } };
console.log('uid', user.uid);
await t('valid create', true, () => setDoc(ref(), { name: 'TEST', score: 20000, ms: 15000, hits: 1, at: serverTimestamp() }));
await t('worse score update', false, () => setDoc(ref(), { name: 'TEST', score: 30000, ms: 30000, hits: 0, at: serverTimestamp() }));
await t('better score update', true, () => setDoc(ref(), { name: 'TEST', score: 12000, ms: 12000, hits: 0, at: serverTimestamp() }));
await t('rename only', true, () => updateDoc(ref(), { name: 'TEST2' }));
await t('wrong formula', false, () => setDoc(ref(), { name: 'TEST', score: 5000, ms: 9000, hits: 0, at: serverTimestamp() }));
await t('too fast', false, () => setDoc(ref(), { name: 'TEST', score: 1000, ms: 1000, hits: 0, at: serverTimestamp() }));
await t('long name', false, () => setDoc(ref(user.uid, '1'), { name: 'X'.repeat(13), score: 9000, ms: 9000, hits: 0, at: serverTimestamp() }));
await t('other uid', false, () => setDoc(ref('someoneelse'), { name: 'HACK', score: 9000, ms: 9000, hits: 0, at: serverTimestamp() }));
await t('players own doc', true, () => setDoc(doc(db, 'players', user.uid), { progress: { stars: {} }, updatedAt: serverTimestamp() }));
await t('players other doc read', false, () => getDoc(doc(db, 'players', 'someoneelse')));
const top = await getDocs(query(collection(db, 'stages', '0', 'scores'), orderBy('score'), limit(10)));
console.log('top', top.docs.map((d) => d.data().name + ':' + d.data().score));
const c = await getCount(query(collection(db, 'stages', '0', 'scores'), where('score', '<', 12000)));
console.log('rank', c.data().count + 1);
console.log('CLEANUP', user.uid);
process.exit(0);
EOF
node --use-system-ca scratch-test.mjs 2>&1 | grep -v "^\s*at "

