        [450, (d) => d.red([[2, 2]])],
        [450, (d) => d.red([[3, 2]])],
        [200, (d) => d.move(0, -1)],
        [250, (d) => d.red([[4, 2]])],
        [300, (d) => d.move(0, -1)],
        [200, (d) => d.red([[3, 2]])],
        [300, (d) => d.move(0, -1)],
        [200, (d) => d.red([[2, 2]])],
        [300, (d) => d.badge('NICE!', 'good')],
      ],
    },
    {
      title: 'RED = LOSE A LIFE',
      sub: '3 lives. Lose them all and it\'s over',
      map: ['.....', '.....', '.....', '.....', '.....'],
      player: [2, 3],
      hud: { lives: true },
      steps: [
        [0, (d) => d.red([[2, 1]])],
        [700, (d) => d.move(0, -1)],
        [600, (d) => d.move(0, -1)],
        [0, (d) => d.hit()],
        [900, (d) => d.move(0, 1)],
      ],
    },
    {
      title: 'GREEN IS SAFE',
      sub: 'Red can\'t enter green. Hide there',
      map: ['.....', '.....', '..G..', '.....', '.....'],
      player: [2, 3],
      steps: [
        [300, (d) => d.sweep(0)],
        [500, (d) => d.sweep(1)],
        [150, (d) => d.move(0, -1)],
        [350, (d) => d.sweep(2)],
        [100, (d) => d.badge('SAFE', 'good')],
        [400, (d) => d.sweep(3)],
        [500, (d) => d.sweep(4)],
        [500, (d) => d.red([])],
      ],
    },
    {
      title: 'BLUE TELEPORTS!',
      sub: 'Blue blinks, then jumps to a new spot',
      map: ['.....', '.B...', '.....', '...B.', '.....'],
      player: [2, 4],
      hud: { blue: true },
      steps: [
        [700, (d) => d.warnBlue(true)],
        [1100, (d) => { d.warnBlue(false); d.teleport([[1, 1], [3, 3]], [[1, 3], [3, 1]]); }],
        [600, (d) => d.move(-1, -1)],
        [550, (d) => d.move(1, -1)],
        [550, (d) => d.move(1, -1)],
