.demo-caption { text-align: center; margin: 18px 0 6px; min-height: 64px; }
.demo-caption b { display: block; font-size: 24px; letter-spacing: 0.1em; color: var(--cyan); text-shadow: 0 0 10px rgba(45, 226, 255, 0.6); }
.demo-caption span { display: block; margin-top: 6px; color: var(--muted); font-size: 14px; }
.demo-hud { display: flex; justify-content: center; gap: 18px; min-height: 22px; font-weight: 700; letter-spacing: 0.1em; }
.demo-timer { width: min(78vw, 300px); margin: 6px auto 0; }
.demo-timer #demoTimeFill { transition: width 1.4s linear; }
.demo-wrap { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; position: relative; }
.demo-board { --cols: 5; --rows: 5; width: min(78vw, 300px, 42dvh); height: min(78vw, 300px, 42dvh); }
.swipe {
  position: absolute; left: 0; top: 0;
  width: calc(100% / var(--cols)); height: calc(100% / var(--rows));
  display: flex; align-items: center; justify-content: center;
  pointer-events: none; z-index: 3;
}
.swipe span { font-size: 30px; color: #fff; text-shadow: 0 0 10px var(--cyan); opacity: 0; }
.swipe.show span { animation: swipe 0.45s ease-out; }
.demo-badge {
  position: absolute; font-size: 44px; font-weight: 900; letter-spacing: 0.08em;
  pointer-events: none; z-index: 4; animation: badge 0.9s ease-out forwards;
}
.demo-badge.good { color: var(--green); text-shadow: 0 0 18px var(--green); }
.demo-badge.bad { color: var(--red); text-shadow: 0 0 18px var(--red); }
.demo-badge.stars { color: #ffd84a; text-shadow: 0 0 18px #ffd84a; }
.demo-dots { display: flex; justify-content: center; gap: 8px; margin: 14px 0; }
.demo-dots .dot { width: 10px; height: 10px; padding: 0; border-radius: 50%; background: var(--line); box-shadow: none; }
.demo-dots .dot.active { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.demo-nav { display: flex; gap: 10px; align-items: center; }
.demo-nav #demoStart { flex: 1; height: 48px; }
#demoStart.pulse { animation: pulse 0.9s infinite alternate; }

@keyframes swipe { from { opacity: 0.9; transform: translateX(-30%); } to { opacity: 0; transform: translateX(60%); } }
