import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const URL_ = 'file:///D:/Gitasin/cybercube/www/index.html';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-cdp`,
  '--remote-debugging-port=9333', '--window-size=390,844', 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) {
    await sleep(250);
    try { target = (await (await fetch('http://127.0.0.1:9333/json')).json()).find((t) => t.type === 'page'); } catch {}
  }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0;
  const pending = new Map();
  ws.addEventListener('message', (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => {
    const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.result.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || 'eval error');
    return r.result.result.value;
  };
  const shot = async (name) => {
    const r = await send('Page.captureScreenshot', { format: 'png' });
    writeFileSync(`${DIR}/${name}.png`, Buffer.from(r.result.data, 'base64'));
  };
  const waitFor = async (expr, ms = 30000) => {
    const end = Date.now() + ms;
    while (Date.now() < end) { if (await ev(expr)) return true; await sleep(200); }
    throw new Error('timeout: ' + expr);
  };

  await send('Page.enable');
  await send('Runtime.enable');
  // 게임 시간 3배속: 매 프레임 0.05초씩 흐르도록 rAF 타임스탬프를 앞당김
  await send('Page.addScriptToEvaluateOnNewDocument', { source: `
    (() => { const raf = window.requestAnimationFrame.bind(window); let t = 0;
      window.requestAnimationFrame = (cb) => raf(() => { t += 50; cb(t); });
      const pn = performance.now.bind(performance); let base = null;
      performance.now = () => t; })();` });
  await send('Page.navigate', { url: URL_ });
  await sleep(800);
  await ev(`localStorage.setItem('cybercube.progress', JSON.stringify({stars:{},best:{},name:'TEST',sound:false,seenDemo:true}));
            localStorage.setItem('cybercube.adMode','release'); true`);
  await send('Page.reload');
  await sleep(800);
  const btns = () => ev(`[...document.querySelectorAll('#modalButtons button')].map(b => b.textContent).join(' | ')`);
  console.log('mode button:', await ev(`document.getElementById('modeBtn').textContent`));

  // 1판: 시간 초과로 실패
  await ev(`document.querySelector('#stageGrid .stage-btn').click(); true`);
  await waitFor(`!document.getElementById('modal').classList.contains('hidden')`, 40000);
  console.log('1st fail:', await ev(`document.getElementById('modalText').textContent`), '→', await btns());
  await shot('ad-1-fail');

  // 보상형 광고 보고 이어하기
  await ev(`document.querySelector('#modalButtons button').click(); true`);
  await sleep(300);
  console.log('rewarded overlay:', await ev(`!document.getElementById('adOverlay').classList.contains('hidden')`), await ev(`document.getElementById('adLabel').textContent`));
  await shot('ad-2-rewarded');
  await waitFor(`!document.getElementById('adClose').classList.contains('hidden')`, 8000);
  await ev(`document.getElementById('adClose').click(); true`);
  await sleep(300);
  console.log('after reward: time =', await ev(`document.getElementById('timeLeft').textContent`), 'modal hidden =', await ev(`document.getElementById('modal').classList.contains('hidden')`));

  // 이어서 다시 시간 초과 → 이번엔 이어하기 버튼 없어야 함
  await waitFor(`!document.getElementById('modal').classList.contains('hidden')`, 30000);
  console.log('2nd fail (continued):', await btns());

  // RETRY → 3판째 실패 → RETRY 누를 때 전면 광고 (결과 2번째에 RETRY는 광고 없음)
  await ev(`[...document.querySelectorAll('#modalButtons button')].find(b => b.textContent === 'RETRY').click(); true`);
  await sleep(300);
  console.log('after 2nd result RETRY, overlay:', await ev(`!document.getElementById('adOverlay').classList.contains('hidden')`));
  await waitFor(`!document.getElementById('modal').classList.contains('hidden')`, 40000);
  console.log('3rd fail:', await btns());
  await ev(`[...document.querySelectorAll('#modalButtons button')].find(b => b.textContent === 'RETRY').click(); true`);
  await sleep(300);
  console.log('after 3rd result RETRY, overlay:', await ev(`!document.getElementById('adOverlay').classList.contains('hidden')`), await ev(`document.getElementById('adLabel').textContent`));
  await shot('ad-3-interstitial');

  // 테스트 모드로 바꾸면 광고 버튼 없음
  await ev(`window.Ads.setMode('test'); true`);
  await waitFor(`!document.getElementById('adClose').classList.contains('hidden')`, 8000);
  await ev(`document.getElementById('adClose').click(); true`);
  await waitFor(`!document.getElementById('modal').classList.contains('hidden')`, 40000);
  console.log('test mode fail:', await btns());
} catch (e) {
  console.log('ERROR', e.message);
} finally {
  ws?.close();
  edge.kill();
}

