input.command:
cd D:/Gitasin/cybercube/www && cat >> style.css <<'EOF'

/* ── LED 바닥 패널 스타일 (실제 매장 바닥처럼) ──
   금속 프레임 + 반투명 유리 패널. 켜지면 가운데가 가장 밝고 안쪽 LED 테두리 선이 빛남.
   이전 스타일로 돌아가려면 이 블록만 지우면 됨 */
.board {
  background: #151821;                                   /* 패널 사이 금속 프레임 */
  box-shadow: 0 0 0 4px #151821, 0 0 0 5px #2a2f3f, 0 8px 24px rgba(0, 0, 0, 0.6);
  border-radius: 3px;
}
.cell::before {
  inset: 2px;
  border-radius: 2px;
  /* 꺼진 패널: 어두운 유리 + 희미한 LED 테두리 선 */
  background: radial-gradient(circle at 50% 45%, #171b2b 0%, #0d0f19 75%);
  border: 1px solid #262b3c;
  box-shadow: inset 0 0 0 4px rgba(0, 0, 0, 0.35), inset 0 0 0 5px rgba(120, 140, 200, 0.08), inset 0 0 10px rgba(0, 0, 0, 0.5);
}
.cell.hole::before {
  background: #030305;                                   /* 패널이 빠진 자리 */
  border-color: #0b0c11;
  box-shadow: inset 0 0 10px #000;
}
.cell.blue::before {
  background: radial-gradient(circle at 50% 50%, #e3edff 0%, #79acff 28%, #2f7bff 62%, #1b4cb4 100%);
  border-color: #a9c8ff;
  box-shadow: inset 0 0 0 4px rgba(20, 60, 160, 0.35), inset 0 0 0 5px rgba(220, 235, 255, 0.85),
    0 0 18px rgba(47, 123, 255, 0.85), 0 0 4px rgba(47, 123, 255, 1);
}
.cell.done::before {
  /* 밟아서 꺼진 패널: 남은 빛이 아주 희미하게 */
  background: radial-gradient(circle at 50% 45%, #18254d 0%, #0e1430 75%);
  border-color: #24335f;
