`    playerEl.style.transform = \`translate(\${d.px * 100}%, \${d.py * 100}%)\`;
    const pi = d.py * N + d.px;
    playerEl.dataset.tint = red.has(pi) ? 'red' : d.tiles[pi] === 'G' ? 'green' : d.tiles[pi] === 'D' ? 'blue' : '';`],
]);
console.log('ok');
EOF
