[`  // 육각형 굴리기:`,
`  // 육각형 깨짐: 6개 면이 각자 바깥쪽으로 흩어짐
  function shatterPlayer() {
    sfx.shatter();
    vibrate([30, 30, 120]);
    restorePlayer();
    playerEl.classList.add('shatter');
    for (let k = 0; k < 6; k++) {
      // 면 k: 가운데 + 인접한 두 꼭짓점 (꼭짓점은 위에서 시계 방향 30°, 90°, ...)
      const v = (deg) => [50 + 50 * Math.sin(deg * Math.PI / 180), 50 - 50 * Math.cos(deg * Math.PI / 180) * 0.866 / 0.866];
      const hex = [[25, 6.7], [75, 6.7], [100, 50], [75, 93.3], [25, 93.3], [0, 50]];
      const a = hex[k];
      const b = hex[(k + 1) % 6];
      const mid = [(a[0] + b[0]) / 2 - 50, (a[1] + b[1]) / 2 - 50];
      const len = Math.hypot(mid[0], mid[1]);
      const shard = document.createElement('div');
      shard.className = 'shard';
      shard.style.clipPath = \`polygon(50% 50%, \${a[0]}% \${a[1]}%, \${b[0]}% \${b[1]}%)\`;
      shard.style.setProperty('--dx', \`\${(mid[0] / len) * (28 + Math.random() * 16)}px\`);
      shard.style.setProperty('--dy', \`\${(mid[1] / len) * (28 + Math.random() * 16) + 10}px\`);
      shard.style.setProperty('--r', \`\${(Math.random() - 0.5) * 160}deg\`);
      shard.style.rotate = \`\${playerEl.rot || 0}deg\`;
      playerEl.appendChild(shard);
      void v;
    }
  }

  function restorePlayer() {
    playerEl.classList.remove('shatter', 'crack-flash');
    playerEl.querySelectorAll('.shard').forEach((s) => s.remove());
  }

  // 육각형 굴리기:`],
]);

// 시연: 생명이 줄면 금
patch('demo.js',[[`    playerEl.style.transform = \`translate(\${d.px * 100}%, \${d.py * 100}%)\`;`,
`    playerEl.style.transform = \`translate(\${d.px * 100}%, \${d.py * 100}%)\`;
    playerEl.dataset.crack = String(Math.min(2, 3 - d.lives));`]]);
console.log('ok');
EOF
