.player {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  /* 미끄러지듯 감속하는 곡선. 이동 중에 다음 이동이 들어오면 현재 위치에서 자연스럽게 이어짐 */
  transition: transform 0.12s cubic-bezier(0.25, 0.8, 0.35, 1);
  pointer-events: none;
  z-index: 2;
}
.player.diag { transition-duration: 0.16s; }
/* 육각형 플레이어
   - 테두리 빛·그림자는 잘린 모양(clip-path)을 따라가도록 filter로
   - ::before = 면이 나뉜 몸체. 한 칸마다 60°씩 굴러감 (--rot, game.js/demo.js가 지정)
   - ::after  = 고정된 조명(왼쪽 위). 육각형은 60° 대칭이라 다 구르면 모양이 딱 겹침 */
.player {
  filter: drop-shadow(0 0 1px rgba(8, 20, 40, 0.9)) drop-shadow(0 0 5px rgba(45, 226, 255, 0.85)) drop-shadow(0 3px 3px rgba(0, 0, 0, 0.6));
}
.player::before,
.player::after {
  content: "";
  position: absolute;
  inset: 18%;
  clip-path: polygon(25% 6.7%, 75% 6.7%, 100% 50%, 75% 93.3%, 25% 93.3%, 0% 50%);
}
.player::before {
  /* 6개 옆면(살짝 다른 밝기) + 가운데 윗면 */
  background:
    radial-gradient(circle, #ffffff 0 29%, rgba(255, 255, 255, 0.35) 30%, transparent 32%),
    conic-gradient(from -30deg, #eef5fa 0 60deg, #b4c7d6 60deg 120deg, #d6e3ec 120deg 180deg,
      #a3b8c9 180deg 240deg, #cddbe6 240deg 300deg, #bccdda 300deg 360deg);
  transform: rotate(var(--rot, 0deg));
  transition: transform 0.16s cubic-bezier(0.3, 0.7, 0.4, 1);
}
.player::after {
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.7) 0%, rgba(255, 255, 255, 0) 42%, rgba(8, 24, 52, 0.55) 100%);
}
.player.invincible { animation: blink 0.15s infinite alternate; }

/* 금: 생명이 줄 때마다 늘어남 (data-crack = 잃은 생명 수). 몸체와 같이 굴러감 */
.player .crack {
  position: absolute;
  inset: 18%;
  width: 64%;
  height: 64%;
  clip-path: polygon(25% 6.7%, 75% 6.7%, 100% 50%, 75% 93.3%, 25% 93.3%, 0% 50%);
  transform: rotate(var(--rot, 0deg));
  transition: transform 0.16s cubic-bezier(0.3, 0.7, 0.4, 1);
  z-index: 1;
  overflow: visible;
}
.player .crack path {
  fill: none;
  stroke: #142233;
  stroke-width: 3;
  stroke-linejoin: round;
  stroke-linecap: round;
  filter: drop-shadow(1px 1px 0 rgba(255, 255, 255, 0.75)); /* 갈라진 틈의 밝은 단면 */
}
.player .crack g { opacity: 0; transition: opacity 0.1s; }
.player[data-crack="1"] .c1,
.player[data-crack="2"] .c1,
.player[data-crack="2"] .c2 { opacity: 1; }
.player.crack-flash .crack { animation: crack-flash 0.35s ease-out; }

/* 깨짐: 몸체는 숨기고 6조각이 흩어짐 */
.player.shatter { animation: none; } /* 맞은 직후 무적 깜빡임이 조각에 걸리지 않게 */
.player.shatter::before,
.player.shatter::after,
.player.shatter .crack { opacity: 0; }
.player .shard {
  position: absolute;
  inset: 18%;
  animation: shard var(--dur, 0.8s) cubic-bezier(0.15, 0.6, 0.35, 1) forwards;
}

@keyframes crack-flash { 0% { filter: brightness(2.2); } 100% { filter: brightness(1); } }
/* 바깥으로 튀었다가 중력처럼 아래로 떨어지며 사라짐 */
@keyframes shard {
  0% { transform: translate(0, 0) rotate(0deg) scale(1); opacity: 1; }
  45% { transform: translate(calc(var(--dx) * 0.75), calc(var(--dy) * 0.75)) rotate(calc(var(--r) * 0.5)) scale(1); opacity: 1; }
  100% { transform: translate(var(--dx), calc(var(--dy) + var(--fall))) rotate(var(--r)) scale(0.8); opacity: 0; }
}

