  function rotate(p, deg) {
    const t = (deg * Math.PI) / 180;
    const x = p[0] - 50;
    const y = p[1] - 50;
    return [50 + x * Math.cos(t) - y * Math.sin(t), 50 + x * Math.sin(t) + y * Math.cos(t)];
  }

